, "pm": {"1": {"ok": true}, "2": {"ok": true}, "3": {"ok": true}, "4": {"ok": true}, "5": {"ok": true}, "6": {"ok": true}, "7": {"ok": true}}, "afb": "II", "correct": ["26/7"], "acceptance": {"canonical": "26/7", "known_errors": {"24/7": "qf_gegenoperation_vorzeichen", "26": "qf_durch_a_vergessen", "32/7": "qf_umstellen_reihenfolge"}}, "parts": null, "figur": null, "optionen": null, "solution": "7x − 1 = 25\n7x = 26\nx = 26 : 7\nx = 26/7", "hints": [{"level": 1, "text": "Was muss weg, damit x allein steht?", "status": "entwurf"}, {"level": 2, "text": "Rechne zuerst auf beiden Seiten + 1.", "status": "entwurf"}, {"level": 3, "text": "Danach steht 7x = … da. Wodurch teilst du?", "status": "entwurf"}]}, {"suffix": "home-s3-841d2bd87d", "input_type": "NUMERIC", "frage": "Löse 8x + 10 = 39. Gib x an.", "payload": {"kind": "short_input", "prompt": "Löse 8x + 10 = 39. Gib x an."}, "params": {"a": 8, "b": 10, "c": 39}, "stufe": 3, "rolle": "home", "pm": {"1": {"ok": true}, "2": {"ok": true}, "3": {"ok": true}, "4": {"ok": true}, "5": {"ok": true}, "6": {"ok": true}, "7": {"ok": true}}, "afb": "II", "correct": ["29/8", "3.625", "3,625"], "acceptance": {"canonical": "29/8", "equivalents": ["3.625", "3,625"], "known_errors": {"49/8": "qf_gegenoperation_vorzeichen", "29": "qf_durch_a_vergessen", "-41/8": "qf_umstellen_reihenfolge", "−41/8": "qf_umstellen_reihenfolge"}}, "parts": null, "figur": null, "optionen": null, "solution": "8x + 10 = 39\n8x = 29\nx = 29 : 8\nx = 29/8", "hints": [{"level": 1, "text": "Was muss weg, damit x allein steht?", "status": "entwurf"}, {"level": 2, "text": "Rechne zuerst auf beiden Seiten − 10.", "status": "entwurf"}, {"level": 3, "text": "Danach steht 8x = … da. Wodurch teilst du?", "status": "entwurf"}]}]'::jsonb)
             as v(suffix text, input_type text, frage text, payload jsonb, params jsonb, stufe int, rolle text,
                  pm jsonb, afb text, correct jsonb, acceptance jsonb, parts jsonb, figur jsonb, optionen jsonb,
                  solution text, hints jsonb)),
     neu as (
  insert into public.tasks (content_type, input_type, status, is_active, title, question, question_payload, parts, skill_key,
                            difficulty, afb, class_level, est_duration_sec, source, source_ref, einsatz, bauform_id,
                            bauform_version, params, stufe, rolle, kernidee_key, pruefmaschine)
  select 'exercise', v.input_type, 'draft', true, 'GL-1' || ' · ' || v.rolle || ' · S' || v.stufe, v.frage,
         v.payload, coalesce(v.parts, '[]'::jsonb), 'gleichung_zweischrittig', v.stufe, v.afb, 9, 60, 'bauform',
         'GL-1' || '-v' || b.version || '-' || v.suffix, '{session}', b.id, b.version, v.params, v.stufe,
         v.rolle, null, v.pm
    from b, v
  on conflict (source, source_ref) do nothing
  returning id, source_ref),
     loes as (
  insert into public.task_solutions (task_id, correct_answers, acceptance, solution, hints)
  select neu.id, v.correct, v.acceptance, v.solution, v.hints
    from neu join b on true join v on neu.source_ref = 'GL-1' || '-v' || b.version || '-' || v.suffix
  returning task_id),
     fig as (
  -- Eine Figur je Aufgabe (task_figures) bzw. je Option einer Graph-Auswahl (task_figur_optionen); hochgeladen
  -- werden sie von scripts/figures/upload_figures.py (Rasit).
  insert into public.task_figures (task_id, generator, params, alt_text)
  select neu.id, v.figur ->> 'generator', v.figur -> 'params', v.figur ->> 'alt'
    from neu join b on true join v on neu.source_ref = 'GL-1' || '-v' || b.version || '-' || v.suffix
   where v.figur is not null
  returning task_id)
insert into public.task_figur_optionen (task_id, option_id, generator, params, alt_text)
select neu.id, o ->> 'option', o ->> 'generator', o -> 'params', o ->> 'alt'
  from neu join b on true join v on neu.source_ref = 'GL-1' || '-v' || b.version || '-' || v.suffix,
       jsonb_array_elements(coalesce(v.optionen, '[]')) o;
do $$ begin perform set_config('edvance.hinweis_status', '', true); perform set_config('edvance.bauform_export', '', true); end $$;
